class Solution {
    private static final int DRAW = 0;
    private static final int MOUSE = 1;
    private static final int CAT = 2;
    private static final int MOUSE_TURN = 0;
    private static final int CAT_TURN = 1;

    public int catMouseGame(int[][] graph) {
        int n = graph.length;
        int[][][] result = new int[n][n][2];
        int[][][] degree = new int[n][n][2];
        for (int mouse = 0; mouse < n; mouse++) {
            for (int cat = 0; cat < n; cat++) {
                degree[mouse][cat][MOUSE_TURN] = graph[mouse].length;
                for (int nextCat : graph[cat]) {
                    if (nextCat != 0) {
                        degree[mouse][cat][CAT_TURN]++;
                    }
                }
            }
        }

        java.util.ArrayDeque<int[]> queue = new java.util.ArrayDeque<>();
        for (int cat = 1; cat < n; cat++) {
            for (int turn = 0; turn < 2; turn++) {
                result[0][cat][turn] = MOUSE;
                queue.offer(new int[]{0, cat, turn, MOUSE});
                result[cat][cat][turn] = CAT;
                queue.offer(new int[]{cat, cat, turn, CAT});
            }
        }

        while (!queue.isEmpty()) {
            int[] state = queue.poll();
            int mouse = state[0];
            int cat = state[1];
            int turn = state[2];
            int winner = state[3];
            int parentTurn = 1 - turn;

            if (parentTurn == MOUSE_TURN) {
                for (int prevMouse : graph[mouse]) {
                    if (result[prevMouse][cat][parentTurn] != DRAW) {
                        continue;
                    }
                    if (winner == MOUSE) {
                        result[prevMouse][cat][parentTurn] = MOUSE;
                        queue.offer(new int[]{prevMouse, cat, parentTurn, MOUSE});
                    } else if (--degree[prevMouse][cat][parentTurn] == 0) {
                        result[prevMouse][cat][parentTurn] = CAT;
                        queue.offer(new int[]{prevMouse, cat, parentTurn, CAT});
                    }
                }
            } else {
                for (int prevCat : graph[cat]) {
                    if (prevCat == 0 || result[mouse][prevCat][parentTurn] != DRAW) {
                        continue;
                    }
                    if (winner == CAT) {
                        result[mouse][prevCat][parentTurn] = CAT;
                        queue.offer(new int[]{mouse, prevCat, parentTurn, CAT});
                    } else if (--degree[mouse][prevCat][parentTurn] == 0) {
                        result[mouse][prevCat][parentTurn] = MOUSE;
                        queue.offer(new int[]{mouse, prevCat, parentTurn, MOUSE});
                    }
                }
            }
        }
        return result[1][2][MOUSE_TURN];
    }
}

class Solution {
    private int[][][] memo;
    private int n;

    public int catMouseGame(int[][] graph) {
        n = graph.length;
        memo = new int[n][n][2 * n * n + 1];
        for (int[][] table : memo) {
            for (int[] row : table) {
                java.util.Arrays.fill(row, -1);
            }
        }
        return solve(graph, 1, 2, 0);
    }

    private int solve(int[][] graph, int mouse, int cat, int turnNumber) {
        if (mouse == 0) {
            return 1;
        }
        if (mouse == cat) {
            return 2;
        }
        if (turnNumber >= 2 * n * n) {
            return 0;
        }
        if (memo[mouse][cat][turnNumber] != -1) {
            return memo[mouse][cat][turnNumber];
        }

        boolean mouseTurn = turnNumber % 2 == 0;
        int best = mouseTurn ? 2 : 1;
        if (mouseTurn) {
            for (int nextMouse : graph[mouse]) {
                int child = solve(graph, nextMouse, cat, turnNumber + 1);
                if (child == 1) {
                    return memo[mouse][cat][turnNumber] = 1;
                }
                if (child == 0) {
                    best = 0;
                }
            }
        } else {
            for (int nextCat : graph[cat]) {
                if (nextCat == 0) {
                    continue;
                }
                int child = solve(graph, mouse, nextCat, turnNumber + 1);
                if (child == 2) {
                    return memo[mouse][cat][turnNumber] = 2;
                }
                if (child == 0) {
                    best = 0;
                }
            }
        }
        return memo[mouse][cat][turnNumber] = best;
    }
}

class Solution {
    private static final int DRAW = 0;
    private static final int MOUSE = 1;
    private static final int CAT = 2;

    public int catMouseGame(int[][] graph) {
        int n = graph.length;
        int limit = 2 * n * n;
        int[][] next = terminalLayer(n);

        for (int turn = limit - 1; turn >= 0; turn--) {
            int[][] current = new int[n][n];
            boolean mouseTurn = turn % 2 == 0;
            for (int mouse = 0; mouse < n; mouse++) {
                for (int cat = 0; cat < n; cat++) {
                    if (mouse == 0) {
                        current[mouse][cat] = MOUSE;
                    } else if (mouse == cat) {
                        current[mouse][cat] = CAT;
                    } else if (mouseTurn) {
                        current[mouse][cat] = chooseMouseMove(graph, next, mouse, cat);
                    } else {
                        current[mouse][cat] = chooseCatMove(graph, next, mouse, cat);
                    }
                }
            }
            next = current;
        }
        return next[1][2];
    }

    private int[][] terminalLayer(int n) {
        int[][] layer = new int[n][n];
        for (int mouse = 0; mouse < n; mouse++) {
            for (int cat = 0; cat < n; cat++) {
                if (mouse == 0) {
                    layer[mouse][cat] = MOUSE;
                } else if (mouse == cat) {
                    layer[mouse][cat] = CAT;
                }
            }
        }
        return layer;
    }

    private int chooseMouseMove(int[][] graph, int[][] next, int mouse, int cat) {
        int result = CAT;
        for (int nextMouse : graph[mouse]) {
            int child = next[nextMouse][cat];
            if (child == MOUSE) {
                return MOUSE;
            }
            if (child == DRAW) {
                result = DRAW;
            }
        }
        return result;
    }

    private int chooseCatMove(int[][] graph, int[][] next, int mouse, int cat) {
        int result = MOUSE;
        for (int nextCat : graph[cat]) {
            if (nextCat == 0) {
                continue;
            }
            int child = next[mouse][nextCat];
            if (child == CAT) {
                return CAT;
            }
            if (child == DRAW) {
                result = DRAW;
            }
        }
        return result;
    }
}

import java.util.*;

class Solution {
    private static final int DRAW = 0;
    private static final int MOUSE = 1;
    private static final int CAT = 2;
    private static final int MOUSE_TURN = 0;
    private static final int CAT_TURN = 1;

    @SuppressWarnings("unchecked")
    public int catMouseGame(int[][] graph) {
        int n = graph.length;
        int[][][] color = new int[n][n][2];
        int[][][] degree = new int[n][n][2];
        List<int[]>[][][] parents = new ArrayList[n][n][2];
        for (int mouse = 0; mouse < n; mouse++) {
            for (int cat = 0; cat < n; cat++) {
                for (int turn = 0; turn < 2; turn++) {
                    parents[mouse][cat][turn] = new ArrayList<>();
                }
            }
        }

        for (int mouse = 0; mouse < n; mouse++) {
            for (int cat = 1; cat < n; cat++) {
                degree[mouse][cat][MOUSE_TURN] = graph[mouse].length;
                for (int nextMouse : graph[mouse]) {
                    parents[nextMouse][cat][CAT_TURN].add(new int[]{mouse, cat, MOUSE_TURN});
                }
                for (int nextCat : graph[cat]) {
                    if (nextCat == 0) {
                        continue;
                    }
                    degree[mouse][cat][CAT_TURN]++;
                    parents[mouse][nextCat][MOUSE_TURN].add(new int[]{mouse, cat, CAT_TURN});
                }
            }
        }

        ArrayDeque<int[]> queue = new ArrayDeque<>();
        for (int cat = 1; cat < n; cat++) {
            for (int turn = 0; turn < 2; turn++) {
                color[0][cat][turn] = MOUSE;
                queue.offer(new int[]{0, cat, turn, MOUSE});
                color[cat][cat][turn] = CAT;
                queue.offer(new int[]{cat, cat, turn, CAT});
            }
        }

        while (!queue.isEmpty()) {
            int[] state = queue.poll();
            int mouse = state[0];
            int cat = state[1];
            int turn = state[2];
            int winner = state[3];
            for (int[] parent : parents[mouse][cat][turn]) {
                int prevMouse = parent[0];
                int prevCat = parent[1];
                int prevTurn = parent[2];
                if (color[prevMouse][prevCat][prevTurn] != DRAW) {
                    continue;
                }
                if ((prevTurn == MOUSE_TURN && winner == MOUSE)
                        || (prevTurn == CAT_TURN && winner == CAT)) {
                    color[prevMouse][prevCat][prevTurn] = winner;
                    queue.offer(new int[]{prevMouse, prevCat, prevTurn, winner});
                } else if (--degree[prevMouse][prevCat][prevTurn] == 0) {
                    int losingWinner = prevTurn == MOUSE_TURN ? CAT : MOUSE;
                    color[prevMouse][prevCat][prevTurn] = losingWinner;
                    queue.offer(new int[]{prevMouse, prevCat, prevTurn, losingWinner});
                }
            }
        }
        return color[1][2][MOUSE_TURN];
    }
}

class Solution {
    private static final int DRAW = 0;
    private static final int MOUSE = 1;
    private static final int CAT = 2;
    private static final int MOUSE_TURN = 0;
    private static final int CAT_TURN = 1;

    public int catMouseGame(int[][] graph) {
        int n = graph.length;
        int[][][] outcome = new int[n][n][2];
        for (int cat = 1; cat < n; cat++) {
            for (int turn = 0; turn < 2; turn++) {
                outcome[0][cat][turn] = MOUSE;
                outcome[cat][cat][turn] = CAT;
            }
        }

        boolean changed = true;
        while (changed) {
            changed = false;
            for (int mouse = 1; mouse < n; mouse++) {
                for (int cat = 1; cat < n; cat++) {
                    if (mouse == cat) {
                        continue;
                    }
                    if (outcome[mouse][cat][MOUSE_TURN] == DRAW) {
                        int resolved = mouseOutcome(graph, outcome, mouse, cat);
                        if (resolved != DRAW) {
                            outcome[mouse][cat][MOUSE_TURN] = resolved;
                            changed = true;
                        }
                    }
                    if (outcome[mouse][cat][CAT_TURN] == DRAW) {
                        int resolved = catOutcome(graph, outcome, mouse, cat);
                        if (resolved != DRAW) {
                            outcome[mouse][cat][CAT_TURN] = resolved;
                            changed = true;
                        }
                    }
                }
            }
        }
        return outcome[1][2][MOUSE_TURN];
    }

    private int mouseOutcome(int[][] graph, int[][][] outcome, int mouse, int cat) {
        boolean allCatWins = true;
        for (int nextMouse : graph[mouse]) {
            int child = outcome[nextMouse][cat][CAT_TURN];
            if (child == MOUSE) {
                return MOUSE;
            }
            if (child != CAT) {
                allCatWins = false;
            }
        }
        return allCatWins ? CAT : DRAW;
    }

    private int catOutcome(int[][] graph, int[][][] outcome, int mouse, int cat) {
        boolean allMouseWins = true;
        for (int nextCat : graph[cat]) {
            if (nextCat == 0) {
                continue;
            }
            int child = outcome[mouse][nextCat][MOUSE_TURN];
            if (child == CAT) {
                return CAT;
            }
            if (child != MOUSE) {
                allMouseWins = false;
            }
        }
        return allMouseWins ? MOUSE : DRAW;
    }
}
